import torch
from enum import Enum
from typing import *

class SomeEnum(Enum):
    A = 0
    B = 1
    C = 2
    D = 3


class DoNothing(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x, e):
        return x

    @staticmethod
    def backward(ctx, g):
        return g

@torch.compile(backend="eager", fullgraph=True)
def f(x):
    output = DoNothing.apply(
        input,
        SomeEnum.A,
    )
    return output

input = torch.tensor([[1., 2, 3], [4, 5, 6]], requires_grad=True)
y = f(input)
